import cardsUrl from '../data/scryfall-cards.generated.json?url'
import printingsUrl from '../data/scryfall-printings.generated.json?url'
import tokenArtsUrl from '../data/scryfall-token-arts.generated.json?url'

/**
 * Offline Scryfall image index: name -> uuid card map, set/number -> uuid
 * printing map and token art table, shipped with the bundle as static assets
 * (generated by `scripts/build-scryfall-image-index.mjs`). All image URLs are
 * built as direct `cards.scryfall.io` CDN paths from the uuid — the CDN is not
 * rate-limited, unlike `api.scryfall.com` (2 req/s on /cards/named + /cards/search,
 * which is why resolving a full board against the API used to fail).
 * A map miss returns null and the UI renders the card-text placeholder; there
 * is deliberately NO live-API fallback.
 */

export type ImageSize = 'small' | 'normal' | 'large' | 'art_crop'

export interface ScryfallTokenArt {
  id: string
  set: string
  num: string
  released: string | null
}

export interface ScryfallImageIndex {
  cards: Record<string, string>
  backs: Set<string>
  printings: Record<string, [string, string]>
  tokenArts: Record<string, ScryfallTokenArt[]>
}

export interface CardRefLike {
  cardName?: string | null
  setCode?: string | null
  cardNumber?: string | null
}

interface CardsFile {
  cards: Record<string, string>
  backs: string[]
}

interface PrintingsFile {
  printings: Record<string, [string, string]>
}

interface TokenArtsFile {
  tokens: Record<string, ScryfallTokenArt[]>
}

let indexPromise: Promise<ScryfallImageIndex> | null = null
let testIndex: ScryfallImageIndex | null = null

/** Test seam: resolves every lookup against an in-memory index without fetching. */
export function setImageIndexForTests(index: ScryfallImageIndex | null): void {
  testIndex = index
  indexPromise = null
}

async function fetchJson<T>(url: string): Promise<T> {
  const res = await fetch(url)
  if (!res.ok) {
    throw new Error(`Scryfall image index asset failed: ${url} -> ${res.status}`)
  }
  return (await res.json()) as T
}

/**
 * Loads the three index assets once (first call), keeps the parsed index in
 * memory for the session. A failed load is not cached: the next call retries.
 */
export function loadImageIndex(): Promise<ScryfallImageIndex> {
  if (testIndex) return Promise.resolve(testIndex)
  if (!indexPromise) {
    indexPromise = Promise.all([
      fetchJson<CardsFile>(cardsUrl),
      fetchJson<PrintingsFile>(printingsUrl),
      fetchJson<TokenArtsFile>(tokenArtsUrl),
    ])
      .then(([cards, printings, tokens]) => ({
        cards: cards.cards,
        backs: new Set(cards.backs),
        printings: printings.printings,
        tokenArts: tokens.tokens,
      }))
      .catch((err: unknown) => {
        indexPromise = null
        throw err
      })
  }
  return indexPromise
}

export interface BootWarmOptions {
  /** Runs `task` when the browser is idle; when omitted, `requestIdleCallback` is used if present. */
  idle?: (task: () => void) => void
  /** Runs `task` after `ms` when no idle scheduler is available; `setTimeout` by default. */
  timeout?: (task: () => void, ms: number) => void
  /** Delay handed to `timeout` on the fallback path (default 0 — let first paint settle). */
  fallbackDelayMs?: number
}

/**
 * Fires the boot warm-up loaders off the first-paint critical path: each is
 * invoked once when the browser goes idle (`requestIdleCallback`), or after a
 * `setTimeout` tick where there is no idle scheduler. Every loader's rejection
 * (and a synchronous throw) is swallowed exactly as the fire-and-forget boot
 * calls did, so a visitor who only opens the login screen and leaves is left
 * with no pending request and no unhandled rejection. Nothing waits on this to
 * have completed: consumers read `loadImageIndex()` / `ensureBundledDecksLoaded()`
 * themselves and fill in whenever the load lands.
 */
export function scheduleBootWarm(
  loaders: ReadonlyArray<() => unknown>,
  options: BootWarmOptions = {},
): void {
  const run = () => {
    for (const load of loaders) {
      try {
        void Promise.resolve(load()).catch(() => {})
      } catch {
        // a synchronous throw from a loader is swallowed like a rejection
      }
    }
  }
  const idle =
    options.idle ??
    (typeof requestIdleCallback === 'function'
      ? (task: () => void) => {
          requestIdleCallback(() => task())
        }
      : undefined)
  if (idle) {
    idle(run)
    return
  }
  const delay = options.fallbackDelayMs ?? 0
  if (options.timeout) options.timeout(run, delay)
  else setTimeout(run, delay)
}

/** NFD + strip combining marks — mirrors the builder's accent folding. */
export function foldName(name: string): string {
  return name.normalize('NFD').replace(/\p{Mn}/gu, '')
}

/**
 * Direct CDN URL for a Scryfall card uuid. `cards.scryfall.io` serves every
 * size off the same uuid path (`front`/`back` swap for the card's back face).
 */
export function cdnUrl(uuid: string, size: ImageSize, back = false): string {
  return `https://cards.scryfall.io/${size}/${back ? 'back' : 'front'}/${uuid[0]}/${uuid[1]}/${uuid}.jpg`
}

export function lookupCardUuid(index: ScryfallImageIndex, name: string): string | null {
  return index.cards[name] ?? index.cards[foldName(name)] ?? null
}

export function hasBackFace(index: ScryfallImageIndex, name: string): boolean {
  return index.backs.has(name) || index.backs.has(foldName(name))
}

export function lookupPrinting(
  index: ScryfallImageIndex,
  setCode: string,
  cardNumber: string,
): { uuid: string; name: string } | null {
  if (!setCode || !cardNumber) return null
  const hit = index.printings[`${setCode}/${cardNumber}`.toLowerCase()]
  return hit ? { uuid: hit[0], name: hit[1] } : null
}

function tokenCandidates(rawName: string): string[] {
  const out: string[] = []
  for (const variant of [rawName, rawName.replace(/-/g, ' ')]) {
    const stripped = variant.replace(/\s+Token$/i, '').trim()
    if (stripped && !out.includes(stripped)) out.push(stripped)
  }
  return out
}

/**
 * Case-insensitive fallback for slug-built lookups (`tgrn/goblin` carries the
 * lowercased name while the table keys keep the printed casing).
 */
const lowerTokenCache = new WeakMap<ScryfallImageIndex, Map<string, { name: string; arts: ScryfallTokenArt[] }>>()

function tokenArtsCaseInsensitive(index: ScryfallImageIndex, name: string): { name: string; arts: ScryfallTokenArt[] } | undefined {
  let map = lowerTokenCache.get(index)
  if (!map) {
    map = new Map()
    for (const [key, arts] of Object.entries(index.tokenArts)) {
      const lower = key.toLowerCase()
      if (!map.has(lower)) map.set(lower, { name: key, arts })
    }
    lowerTokenCache.set(index, map)
  }
  return map.get(name.toLowerCase())
}

/**
 * Token art by name, preferring an art printed in `preferredSet` (the engine's
 * set of the permanent, e.g. `tgrn` for `tgrn/4`) so the board keeps the
 * engine-selected printing when several sets printed the same token.
 */
export function lookupTokenArt(
  index: ScryfallImageIndex,
  rawName: string,
  preferredSet = '',
): { uuid: string; name: string } | null {
  const wanted = preferredSet.trim().toLowerCase()
  for (const candidate of tokenCandidates(rawName)) {
    const folded = foldName(candidate)
    const direct = index.tokenArts[candidate] ?? (folded !== candidate ? index.tokenArts[folded] : undefined)
    const insensitive = direct ? undefined : tokenArtsCaseInsensitive(index, candidate)
    const arts = direct ?? insensitive?.arts
    if (!arts || arts.length === 0) continue
    const preferred = wanted ? arts.find((art) => art.set === wanted) : undefined
    const chosen = preferred ?? arts[0]
    return { uuid: chosen.id, name: direct ? candidate : (insensitive?.name ?? candidate) }
  }
  return null
}

export interface OfflineImage {
  url: string
  name?: string
}

/**
 * Offline equivalent of the old candidate-URL chain. Handles the three key
 * shapes `cardImages.cardKey` produces (`named:Name[#back]`, `tSET/num[#back]`
 * or `tSET/slug[#back]`, `SET/num[#back]`) and returns the CDN URL or null.
 */
export function resolveKeyImage(
  index: ScryfallImageIndex,
  key: string,
  size: ImageSize = 'normal',
): OfflineImage | null {
  const isBack = key.endsWith('#back')
  const clean = key.replace(/#back$/, '')

  if (clean.startsWith('named:')) {
    const name = clean.slice(6).trim()
    if (!name) return null
    const uuid = lookupCardUuid(index, name)
    if (!uuid) return null
    return { url: cdnUrl(uuid, size, isBack && hasBackFace(index, name)), name }
  }

  const slash = clean.indexOf('/')
  if (slash <= 0 || slash === clean.length - 1) return null
  const direct = lookupPrinting(index, clean.slice(0, slash), clean.slice(slash + 1))
  if (direct) {
    return { url: cdnUrl(direct.uuid, size, isBack && hasBackFace(index, direct.name)), name: direct.name }
  }

  const tokenKey = /^t([a-z0-9_]+)\/(.+)$/i.exec(clean)
  if (tokenKey) {
    const hit = lookupTokenArt(index, tokenKey[2], `t${tokenKey[1]}`)
    if (hit) return { url: cdnUrl(hit.uuid, size, isBack), name: hit.name }
  }
  return null
}

/** Printing first, then exact/folded name — the offline `fetchCardJson` order. */
export function resolveCardRefImage(
  index: ScryfallImageIndex,
  ref: CardRefLike,
  size: ImageSize = 'art_crop',
): string | null {
  const setCode = ref.setCode ?? ''
  const cardNumber = ref.cardNumber ?? ''
  if (setCode && cardNumber && cardNumber !== '0') {
    const hit = lookupPrinting(index, setCode, cardNumber)
    if (hit) return cdnUrl(hit.uuid, size, false)
  }
  const name = (ref.cardName ?? '').trim()
  if (name) {
    const uuid = lookupCardUuid(index, name)
    if (uuid) return cdnUrl(uuid, size, false)
  }
  return null
}

/** Async wrapper for hooks: awaits the index, returns null on any failure. */
export async function resolveArtUrl(ref: CardRefLike): Promise<string | null> {
  try {
    const index = await loadImageIndex()
    return resolveCardRefImage(index, ref, 'art_crop')
  } catch {
    return null
  }
}
